    "rhombus":function(){var a=ri(3,5),b=ri(2,a-1)*0.8;return {P:[[0,-b],[a,0],[0,b],[-a,0]],ax:2,cen:true};},
    "parallelogram":function(){var w=ri(4,6),h=ri(2,3),p=ri(1,2);return {P:[[0,0],[w,0],[w+p,h],[p,h]],ax:0,cen:true};},
