    "isosceles trapezium":function(){var w=ri(5,7),t=ri(2,w-2),h=ri(2,3);if((w-t)%2)t--;return {P:[[0,0],[w,0],[(w+t)/2,h],[(w-t)/2,h]],ax:1,cen:false};},
