  var SNAMES=Object.keys(SHAPES);

  var NAMES=["Siobhán","Darragh","Niamh","Oisín","Aoife","Cian","Róisín","Eoin","Ciara","Seán","Méabh","Tadhg"];

  /* ---------- the transformation that a question asks for ---------- */
  function lineAt(){var r=Math.random();if(r<.25)return {t:"y",c:0};if(r<.5)return {t:"x",c:0};if(r<.62)return {t:"d"};if(r<.72)return {t:"e"};return Math.random()<.5?{t:"y",c:rnd([-2,-1,1,2])}:{t:"x",c:rnd([-2,-1,1,2])};}
