    var nm=rnd(["P","Q","A","B","K"]),g=pic!==true&&(pic===false||Math.random()<.35)?"":plane({R:R,lines:a.lines,pts:(a.pts||[]).concat([{p:P,n:nm}]),aria:"Point "+nm+" on a grid"});
    var why={ax:"Same distance from the mirror line, on the other side.",cs:"Go from "+nm+" to the centre, then the same again: the image is "+cs(I)+".",ro:"Turn the arrow from the centre to "+nm+" a quarter turn "+(a.T.cw?"clockwise":"anticlockwise")+".",tr:"Add the move to each coordinate."}[kind];
    if(kind==="ax"){var L2=a.lines[0];why=L2.t==="x"&&L2.c===0?"Axial symmetry in the x-axis: keep x, change the sign of y.":L2.t==="y"&&L2.c===0?"Axial symmetry in the y-axis: change the sign of x, keep y.":L2.t==="d"||L2.t==="e"?"Count squares at right angles to the line m: the image is the same distance on the other side.":"Count the squares straight across to the line m, then the same number on the other side.";}
