  var _all=[];Object.keys(MAKERS).forEach(function(k){(MAKERS[k]||[]).forEach(function(f){if(_all.indexOf(f)<0)_all.push(f);});});
  if(!MAKERS.mixed||!MAKERS.mixed.length)MAKERS.mixed=_all;
